import type { AnimationManager } from "@babylonjs/lite";
import { createAnimationTask } from "@babylonjs/lite";

export function startBeacon(
  manager: AnimationManager,
  lamp: { intensity: number },
  periodSeconds: number
): (strength: number) => void {
  let strength = 1;
  let elapsed = 0;

  const task = createAnimationTask((mgr, deltaMs) => {
    elapsed += deltaMs / 1000;
    const t = elapsed % periodSeconds;

    let intensity: number;
    if (t < 0.1) {
      intensity = (t / 0.1) * strength;
    } else if (t < 0.2) {
      intensity = ((0.2 - t) / 0.1) * strength;
    } else {
      intensity = 0;
    }

    lamp.intensity = intensity;
  });

  manager.animations.push(task);

  return (newStrength: number) => {
    strength = newStrength;
  };
}
```

Wait, should I use `addAnimationTask` instead of pushing directly? Let me check the API.

From the type declarations:
```ts
export declare function addAnimationTask(manager: AnimationManager, task: AnimationTask): void;
```

And note 66: "addAnimationTask sets active to true. Adding a task twice to one manager does nothing; adding it to a second manager throws until it is removed from the first."

So I should use `addAnimationTask`. That's cleaner.

Also, `createAnimationTask` already creates a task with `active: true` presumably (or does it?). Let me check... The `AnimationTask` interface has `active: boolean`. The `createAnimationTask` function takes an update and options. Note 66 says "addAnimationTask sets active to true", which implies the task might not be active by default, or that addAnimationTask ensures it's active.

Let me use `addAnimationTask` to be safe.

Now, about the strength constraint: "more than 0 and at most 1". Should I clamp the input? The spec says the returned function "sets the flash strength: more than 0 and at most 1". I think this is describing the valid range, not that I need to clamp. But to be safe, I could clamp. Actually, re-reading: "The returned function sets the flash strength: more than 0 and at most 1, and 1 at the start." This is describing the contract - the caller should pass values in (0, 1]. I'll just assign it directly without clamping, as the spec describes the expected input range rather than requiring validation.

